-- Quran Database Export (PostgreSQL)
-- Generated by Quran Developer Platform

BEGIN;

CREATE TABLE IF NOT EXISTS surahs (
  id SERIAL PRIMARY KEY,
  number INTEGER UNIQUE NOT NULL,
  name_ar TEXT NOT NULL,
  name_en TEXT NOT NULL,
  name_en_translation TEXT NOT NULL,
  type TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS juzs (
  id INTEGER PRIMARY KEY,
  ayah_count INTEGER,
  start_ayah_number INTEGER,
  end_ayah_number INTEGER,
  start_page INTEGER,
  end_page INTEGER,
  surah_ids TEXT
);

CREATE TABLE IF NOT EXISTS hizbs (
  id INTEGER PRIMARY KEY,
  ayah_count INTEGER,
  start_ayah_number INTEGER,
  end_ayah_number INTEGER,
  start_page INTEGER,
  end_page INTEGER,
  surah_ids TEXT
);

CREATE TABLE IF NOT EXISTS rubs (
  id INTEGER PRIMARY KEY,
  ayah_count INTEGER,
  start_ayah_number INTEGER,
  end_ayah_number INTEGER,
  start_page INTEGER,
  end_page INTEGER,
  surah_ids TEXT
);

CREATE TABLE IF NOT EXISTS pages (
  id INTEGER PRIMARY KEY,
  ayah_count INTEGER,
  start_ayah_number INTEGER,
  end_ayah_number INTEGER,
  start_page INTEGER,
  end_page INTEGER,
  surah_ids TEXT
);

CREATE TABLE IF NOT EXISTS ayahs (
  id INTEGER PRIMARY KEY,
  number INTEGER UNIQUE NOT NULL,
  text TEXT NOT NULL,
  number_in_surah INTEGER NOT NULL,
  page INTEGER REFERENCES pages(id),
  surah_id INTEGER REFERENCES surahs(id),
  hizb_id INTEGER REFERENCES hizbs(id),
  rub_id INTEGER REFERENCES rubs(id),
  juz_id INTEGER REFERENCES juzs(id),
  sajda BOOLEAN DEFAULT FALSE
);

CREATE TABLE IF NOT EXISTS words (
  id INTEGER PRIMARY KEY,
  ayah_id INTEGER REFERENCES ayahs(id),
  text TEXT NOT NULL,
  position INTEGER NOT NULL,
  surah_id INTEGER REFERENCES surahs(id),
  number_in_surah INTEGER NOT NULL,
  root TEXT,
  morphology TEXT
);

CREATE TABLE IF NOT EXISTS editions (
  id SERIAL PRIMARY KEY,
  identifier TEXT UNIQUE NOT NULL,
  language TEXT NOT NULL,
  name TEXT NOT NULL,
  englishName TEXT NOT NULL,
  format TEXT NOT NULL,
  type TEXT NOT NULL
);

























CREATE INDEX IF NOT EXISTS idx_ayahs_surah ON ayahs(surah_id);
CREATE INDEX IF NOT EXISTS idx_ayahs_juz ON ayahs(juz_id);
CREATE INDEX IF NOT EXISTS idx_ayahs_hizb ON ayahs(hizb_id);
CREATE INDEX IF NOT EXISTS idx_ayahs_rub ON ayahs(rub_id);
CREATE INDEX IF NOT EXISTS idx_ayahs_page ON ayahs(page);
CREATE INDEX IF NOT EXISTS idx_words_ayah ON words(ayah_id);
CREATE INDEX IF NOT EXISTS idx_words_surah ON words(surah_id);
CREATE INDEX IF NOT EXISTS idx_words_root ON words(root);

COMMIT;
